ruleContent.content:
@js:
var regex = /\{\s*"url"\s*:\s*"[^"]+"\s*,\s*"mobile"\s*:\s*"[^"]+"\s*,\s*"isk"\s*:\s*"[^"]+"\s*\}/;
var match = result.match(regex);
if (!match) return "正文提取失败，请检查页面结构";
var jsonObj = JSON.parse(match[0]);
var params = "url=" + encodeURIComponent(jsonObj.url) + 
             "&mobile=" + encodeURIComponent(jsonObj.mobile) + 
             "&isk=" + encodeURIComponent(jsonObj.isk);
let response = java.post("https://www.8xsk.info/conapi.php", params, {
    "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
    "X-Requested-With": "XMLHttpRequest",
    "Origin": "https://www.8xsk.info",
    "Referer": baseUrl,
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
});
JSON.parse(response.body())["content"] || "";

ruleToc.chapterUrl:
@js:
var href = result.select("a").attr("href") || result.attr("href");
if (!href) return "";
if (href.startsWith("http")) return href;
return "https://www.8xsk.info" + (href.startsWith("/") ? href : "/" + href);
